mapper.select:
SELECT DISTINCT cori.oprtr_id , cori.ownr_nm , CAST(AES_DECRYPT(FROM_BASE64(cori.oprtr_nm), 'theimc') AS CHAR(100) CHARACTER SET UTF8MB4) AS oprtr_nm , cori.lbl , cori.rfid_no FROM svc_opr_rfid_data sord JOIN cmm_oprtr_rfid_info cori ON sord.rfid_no = cori.rfid_no WHERE 1=1 AND cori.use_yn = 'Y'
AND ownr_nm IN
#{ownr}
and ownr_nm = #{ownrNm}
AND AES_DECRYPT(FROM_BASE64(oprtr_nm), 'theimc') LIKE CONCAT('%', #{oprtrNm}, '%')
AND sord.tag_dt >= CONCAT(#{startDt}, ' 00:00:00') AND sord.tag_dt <= CONCAT(#{endDt}, ' 23:59:59')
ORDER BY cori.oprtr_id LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*) AS driver_count FROM ( SELECT DISTINCT cori.oprtr_id , cori.ownr_nm , CAST(AES_DECRYPT(FROM_BASE64(cori.oprtr_nm), 'theimc') AS CHAR(100) CHARACTER SET UTF8MB4) AS oprtr_nm , cori.lbl , cori.rfid_no FROM svc_opr_rfid_data sord JOIN cmm_oprtr_rfid_info cori ON sord.rfid_no = cori.rfid_no WHERE 1=1 AND cori.use_yn = 'Y'
AND ownr_nm IN
#{ownr}
and ownr_nm = #{ownrNm}
AND AES_DECRYPT(FROM_BASE64(oprtr_nm), 'theimc') LIKE CONCAT('%', #{oprtrNm}, '%')
AND sord.tag_dt >= CONCAT(#{startDt}, ' 00:00:00') AND sord.tag_dt <= CONCAT(#{endDt}, ' 23:59:59')
) AS distinct_drivers

SELECT data_sn , mt_id , rfid_no , tag_dt , reg_dt FROM svc_opr_rfid_data WHERE 1=1 AND rfid_no = #{rfidNo}
AND tag_dt >= CONCAT(#{startDt}, ' 00:00:00') AND tag_dt <= CONCAT(#{endDt}, ' 23:59:59')
ORDER BY tag_dt
asc
desc
LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

